use kni_geometry_prototypes::*;
fn rect(w:f64,y:f64)->Geometry{let p=|x,y|Point{x,y};Geometry{advance:w+2.,rings:vec![Ring{start:p(0.,y),spans:vec![Span::Line(p(w,y)),Span::Line(p(w,y+10.)),Span::Line(p(0.,y+10.)),Span::Line(p(0.,y))]}]}}
fn rule()->Rule{Rule{minimum_training:4,gauge_statistic:GaugeStatistic::Median,maximum_unique_training:512,coverage_numerator:1,coverage_denominator:2,flatten_fraction:1./1024.,bootstrap_replicates:4,stability_fraction:0.5}}
#[test]fn streaming_matches_string_bytes_available_unavailable_aliases_and_order(){let r=rule();let normal=vec![rect(2.,0.),rect(2.1,0.),rect(2.2,0.),rect(8.,0.),rect(8.1,0.),rect(8.2,0.)];let mut aliases=normal.clone();aliases.extend(normal.iter().cloned());let cases=vec![normal,aliases,vec![],vec![rect(2.,0.)]];for xs in cases{let a=fit(&xs,r.clone(),&r.pin()).unwrap();let text=a.canonical_receipt().unwrap();let(count,lines,_)=a.canonical_receipt_counted().unwrap();assert_eq!(count,text.len() as u64);assert_eq!(lines,text.bytes().filter(|b|*b==b'\n').count() as u64);assert_eq!(hash(text.as_bytes()),a.canonical_receipt_counted().unwrap().2);assert_eq!(a.pin(),a.canonical_receipt_counted().unwrap().2);let mut reversed=xs.clone();reversed.reverse();let b=fit(&reversed,r.clone(),&r.pin()).unwrap();assert_eq!(text,b.canonical_receipt().unwrap());assert_eq!(a.pin(),b.pin());}}
